const output = $input.first().json.output;
let data = output;
if (typeof output === 'string') {
  const start = output.indexOf('{');
  const end = output.lastIndexOf('}');
  const cleaned = output.slice(start, end + 1);
  data = JSON.parse(cleaned);
}
return [{ json: data }];

